#!/bin/sh
set -e

# JWT keypair (lexik/jwt-authentication-bundle): config/jwt/*.pem is
# gitignored (private keys must never be committed), and unlike a
# Codespace - where this was generated by hand once as part of the
# manual bootstrap checklist (README "Points d'attention" #11) - a
# Render Docker deploy has no separate "build command" step to run it
# in. The container just booted straight into apache2-foreground with
# no keypair, which stayed invisible: /api/health and every read
# endpoint (funding, sources...) work fine with no keys at all, only
# /api/auth/login (the only place a JWT actually gets signed) 500s.
#
# Generated on every container start rather than baked into the image:
# idempotent (skipped once the files already exist - e.g. a mounted
# persistent disk across restarts of the same instance), and avoids
# committing a keypair - even a throwaway one - into a Docker image
# that could be pulled/inspected by anyone with registry access.
if [ ! -f config/jwt/private.pem ] || [ ! -f config/jwt/public.pem ]; then
  mkdir -p config/jwt
  php bin/console lexik:jwt:generate-keypair --no-interaction
  chown -R www-data:www-data config/jwt
fi

# A3.14 (2026-09-25) : applique les migrations Doctrine en attente a
# chaque demarrage. Necessaire car Render (palier gratuit utilise par ce
# projet) n'offre pas d'onglet Shell pour lancer
# `doctrine:migrations:migrate` a la main apres un deploiement, contrairement
# a un Codespace de developpement - sans cette etape, tout endpoint touchant
# une colonne/table ajoutee par une migration recente casse silencieusement
# en production des que le nouveau code est deploye mais que le schema, lui,
# ne l'est pas encore (vecu en direct le 2026-09-25 avec Opportunity/Tender).
# Idempotent : sans migration en attente, la commande ne fait rien et sort
# en succes - memes garanties que Doctrine Migrations lui-meme (chaque
# migration n'est appliquee qu'une seule fois, suivie dans la table
# doctrine_migration_versions). `set -e` en tete de ce script fait
# volontairement echouer tout le demarrage si une migration echoue - faire
# tourner le code neuf contre un schema qui ne correspond pas serait pire
# qu'un service qui ne demarre pas.
php bin/console doctrine:migrations:migrate --no-interaction

# A3.14 (2026-09-25) : seme les donnees de demonstration Opportunity/Tender
# si elles sont absentes - meme contexte que la commande de migration
# juste au-dessus (pas de Shell disponible sur le palier Render gratuit).
# Voir App\Command\SeedDemoEnrichmentCommand pour le detail de son
# idempotence (jamais via doctrine:fixtures:load, qui purge toute la
# base - voir sa propre docblock pour l'incident qui a motive ce choix).
php bin/console app:seed-demo-enrichment

# Symfony cache (var/cache/{env}) : incident reel de production le
# 2026-09-24 (audit pre-production, validation finale) - sur le disque
# Render de ce service, seul le sous-dossier var/cache DEJA present
# depuis un tout premier deploiement a les bonnes permissions ; tout
# sous-dossier var/cache/{env} pas encore cree echoue en "Permission
# denied" des qu'Apache (worker en www-data, jamais root) essaie de le
# creer lui-meme a la premiere requete - reproduit en direct en passant
# APP_ENV a "prod" (jamais reconstruit avant), qui a casse toute la
# prod (500 partout) jusqu'a revenir en arriere. Prechauffe ici, en
# root, avant qu'Apache ne demarre - meme principe que la paire de cles
# JWT ci-dessus : cree le dossier avec les bonnes permissions une fois
# pour toutes, quel que soit APP_ENV reellement utilise, avant qu'aucune
# requete n'en ait besoin.
mkdir -p var/cache var/log
php bin/console cache:warmup --no-interaction
chown -R www-data:www-data var

exec "$@"
